(function(){
  function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){var t=b;b=a%b;a=t;}return a||1;}
  function reduce(w,h){var g=gcd(w,h);return {w:w/g,h:h/g};}
  function parseRatio(s){var m=String(s).match(/^\s*(\d+)\s*[:/]\s*(\d+)\s*$/);if(!m)return null;return {w:parseInt(m[1],10),h:parseInt(m[2],10)};}
