  function fromOne(a,ratio,axis){var r=parseRatio(ratio);if(!r)return{error:'比例格式如 16:9'};if(axis==='w'){return {value:{w:a,h:Math.round(a*r.h/r.w)}};}else{return {value:{h:a,w:Math.round(a*r.w/r.h)}};}}
